8	import React, { useState, useEffect, useMemo } from 'react';
9	import { useHistory, useLocation } from 'react-router-dom';
10	import { StorefrontPreview } from '@salesforce/commerce-sdk-react/components';
11	import { getAssetUrl, getRouterBasePath } from '@salesforce/pwa-kit-react-sdk/ssr/universal/utils';
12	import useActiveData from '@salesforce/retail-react-app/app/hooks/use-active-data';
13	import { useQuery } from '@tanstack/react-query';
14	import { useAccessToken, useCategory, useShopperBasketsMutation, useUsid } from '@salesforce/commerce-sdk-react';
15	import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
16	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
17	import { useAppOrigin } from '@salesforce/retail-react-app/app/hooks/use-app-origin';
18	import logger from '@salesforce/retail-react-app/app/utils/logger-instance';
19	
20	// Chakra
21	import { SkipNavContent, SkipNavLink } from '@chakra-ui/skip-nav';
22	import {
23	  Box,
24	  Center,
25	  Fade,
26	  Spinner,
27	  useDisclosure,
28	  useStyleConfig,
29	} from '@salesforce/retail-react-app/app/components/shared/ui';
30	
31	// Contexts
32	import { CurrencyProvider } from '@salesforce/retail-react-app/app/contexts';
33	
34	// Local Project Components
35	// SFCC-863 — Header/Footer/DrawerMenu/ListMenu are all already overridden; imported via
36	// relative paths rather than the base SFCC path per overrideStyling.md's "importing an
37	// already-overridden component" rule. The webpack ccExtensibility resolver would redirect
38	// either path form correctly in the real dev server/production build, but Storybook and
39	// Vitest skip that resolver entirely, so a base-path import here would silently exercise
40	// the unstyled base SFCC version in any story/test that renders this component.
41	import AboveHeader from '@salesforce/retail-react-app/app/components/_app/partials/above-header';
42	import { DrawerMenu } from '../drawer-menu';
43	import Footer from '../footer';
44	import Header from '../header';
45	import Island from '@salesforce/retail-react-app/app/components/island';
46	import { ListMenu, ListMenuContent } from '../list-menu';
47	import OfflineBanner from '@salesforce/retail-react-app/app/components/offline-banner';
48	import OfflineBoundary from '@salesforce/retail-react-app/app/components/offline-boundary';
49	import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive';
50	import ScrollToTop from '@salesforce/retail-react-app/app/components/scroll-to-top';
51	import { StoreLocatorModal } from '@salesforce/retail-react-app/app/components/store-locator';
52	import CheckoutFooter from '@salesforce/retail-react-app/app/pages/checkout/partials/checkout-footer';
53	import CheckoutHeader from '@salesforce/retail-react-app/app/pages/checkout/partials/checkout-header';
54	
55	// Hooks
56	import { AddToCartModalProvider } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
57	import { AuthModal, useAuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
58	import { BonusProductSelectionModalProvider } from '@salesforce/retail-react-app/app/hooks/use-bonus-product-selection-modal';
59	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
60	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
61	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
62	import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
63	import { useUpdateShopperContext } from '@salesforce/retail-react-app/app/hooks/use-update-shopper-context';
64	
65	// HOCs
66	import { withCommerceSdkReact } from '@salesforce/retail-react-app/app/components/with-commerce-sdk-react/with-commerce-sdk-react';
67	
68	import { PageDesignerProvider } from '@salesforce/commerce-sdk-react/page-designer';
69	import PageDesignerInit from '@salesforce/retail-react-app/app/components/page-designer-init';
70	
71	// Localization
72	import { IntlProvider } from 'react-intl';
73	
74	// Others
75	import {
76	  CAT_MENU_DEFAULT_NAV_SSR_DEPTH,
77	  CAT_MENU_DEFAULT_ROOT_CATEGORY,
78	  DEFAULT_LOCALE,
79	  DEFAULT_SITE_TITLE,
80	  HOME_HREF,
81	  STORE_LOCATOR_IS_ENABLED,
82	  THEME_COLOR,
83	} from '@salesforce/retail-react-app/app/constants';
84	import { fetchTranslations, getTargetLocale } from '@salesforce/retail-react-app/app/utils/locale';
85	import { flatten, isServer, watchOnlineStatus } from '@salesforce/retail-react-app/app/utils/utils';
86	
87	import Seo from '@salesforce/retail-react-app/app/components/seo';
88	import ShopperAgent from '@salesforce/retail-react-app/app/components/shopper-agent';
89	import { initializeRegistry } from '@salesforce/retail-react-app/app/page-designer/registry';
90	
91	// Initialize registry synchronously at module load time so components are available during SSR
92	initializeRegistry();
93	import { getCommerceAgentConfig } from '@salesforce/retail-react-app/app/utils/config-utils';
94	import { getPathWithLocale } from '@salesforce/retail-react-app/app/utils/url';
95	import { useShopperAgent } from '@salesforce/retail-react-app/app/hooks/use-shopper-agent';
96	
97	type AppProps = {
98	  children: React.ReactNode;
99	};
100	
101	type CategoryNode = {
102	  id: string;
103	  categories?: Record<string, CategoryNode>;
104	  [key: string]: unknown;
105	};
106	
107	const PlaceholderComponent = (): React.ReactElement => (
108	  <Center p="2">
109	    <Spinner size="lg" />
110	  </Center>
111	);
112	
113	const DrawerMenuItemWithData = withCommerceSdkReact(
114	  // any: withCommerceSdkReact's injected item-component props aren't typed upstream;
115	  // narrowing here would require re-deriving withCommerceSdkReact's own generic shape,
116	  // out of scope for a copy-first port.
117	  ({ itemComponent: ItemComponent, data, ...rest }: any) => (
118	    <Fade in={true}>
119	      <ItemComponent {...rest} item={data} itemComponent={DrawerMenuItemWithData} />
120	    </Fade>
121	  ),
122	  {
123	    hook: useCategory,
124	    queryOptions: ({ item }: { item: { id: string } }) => ({
125	      parameters: {
126	        id: item.id,
127	      },
128	    }),
129	    placeholder: PlaceholderComponent,
130	  },
131	);
132	
133	const ListMenuContentWithData = withCommerceSdkReact(
134	  // any: same as DrawerMenuItemWithData above.
135	  ({ data, ...rest }: any) => (
136	    <Fade in={true}>
137	      <ListMenuContent {...rest} item={data} />
138	    </Fade>
139	  ),
140	  {
141	    hook: useCategory,
142	    queryOptions: ({ item }: { item: { id: string } }) => ({
143	      parameters: {
144	        id: item.id,
145	        levels: 2,
146	      },
147	    }),
148	    placeholder: PlaceholderComponent,
149	  },
150	);
151	
152	const App = ({ children }: AppProps): React.ReactElement => {
153	  const { data: categoriesTree } = useCategory({
154	    parameters: { id: CAT_MENU_DEFAULT_ROOT_CATEGORY, levels: CAT_MENU_DEFAULT_NAV_SSR_DEPTH },
155	  });
156	  const categories = flatten((categoriesTree || {}) as CategoryNode, 'categories');
157	  const { getTokenWhenReady } = useAccessToken();
158	  const { usid } = useUsid();
159	  const appOrigin = useAppOrigin();
160	  const activeData = useActiveData();
161	  const history = useHistory();
162	  const location = useLocation();
163	  const authModal = useAuthModal();
164	  const { site, locale, buildUrl } = useMultiSite();
165	  const {
166	    isOpen: isStoreLocatorOpen,
167	    onOpen: onOpenStoreLocator,
168	    onClose: onCloseStoreLocator,
169	  } = useStoreLocatorModal();
170	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
171	  const { req } = useServerContext();
172	
173	  const [isOnline, setIsOnline] = useState(true);
174	  const styles = useStyleConfig('App');
175	  const { isOpen, onOpen, onClose } = useDisclosure();
176	
177	  // Determine Page Designer mode from URL - use req for server-side detection
178	  const pageDesignerMode = useMemo(() => {
179	    const queryParams = location?.search || '';
180	    if (queryParams.includes('mode=EDIT')) return 'EDIT';
181	    else if (queryParams.includes('mode=PREVIEW')) return 'PREVIEW';
182	    return undefined;
183	    // matches upstream base _app exactly.
184	  }, [req?.url]);
185	
186	  const targetLocale = getTargetLocale({
187	    getUserPreferredLocales: () => {
188	      // CONFIG: This function should return an array of preferred locales. They can be
189	      // derived from various sources. Below are some examples of those:
190	      //
191	      // - client side: window.navigator.languages
192	      // - the page URL they're on (example.com/en-GB/home)
193	      // - cookie (if their previous preference is saved there)
194	      //
195	      // If this function returns an empty array (e.g. there isn't locale in the page url),
196	      // then the app would use the default locale as the fallback.
197	
198	      // NOTE: Your implementation may differ, this is just what we did.
199	      return [locale?.id || DEFAULT_LOCALE];
200	    },
201	    l10nConfig: site.l10n,
202	  });
203	
204	  // If the translation file exists, it'll be served directly from static folder (and won't reach this code here).
205	  // However, if the file is missing, the App would render a 404 page.
206	  const is404ForMissingTranslationFile = /\/static\/translations\/compiled\/[^.]+\.json$/.test(location?.pathname);
207	
208	  // Fetch the translation message data using the target locale.
209	  const { data: messages } = useQuery({
210	    queryKey: ['app', 'translations', 'messages', targetLocale],
211	    queryFn: () => {
212	      if (is404ForMissingTranslationFile) {
213	        // Return early to prevent an infinite loop
214	        // Otherwise, it'll continue to fetch the missing translation file again
215	        return {};
216	      }
217	      return fetchTranslations(targetLocale, appOrigin);
218	    },
219	    enabled: isServer,
220	  });
221	
222	  // Used to conditionally render header/footer for checkout page
223	  const isCheckout = /\/checkout$/.test(location?.pathname);
224	
225	  const { l10n } = site;
226	  // Get the current currency to be used through out the app
227	  const currency = locale.preferredCurrency || l10n.defaultCurrency;
228	
229	  // Handle creating a new basket if there isn't one already assigned to the current
230	  // customer.
231	  const { data: customer } = useCurrentCustomer();
232	  const { data: basket, dataUpdatedAt: basketQueryLastUpdateTime } = useCurrentBasket();
233	  const config = getConfig();
234	
235	  const updateBasket = useShopperBasketsMutation('updateBasket');
236	  const updateCustomerForBasket = useShopperBasketsMutation('updateCustomerForBasket');
237	
238	  useEffect(() => {
239	    // update the basket currency if it doesn't match the current locale currency
240	    if (basket?.currency && basket?.currency !== currency) {
241	      updateBasket.mutate({
242	        parameters: { basketId: basket.basketId },
243	        body: { currency },
244	      });
245	    }
246	    // matches upstream base _app exactly.
247	  }, [basket?.currency]);
248	
249	  const commerceAgentConfiguration = useMemo(() => {
250	    return getCommerceAgentConfig();
251	    // matches upstream base _app exactly.
252	  }, [config.app.commerceAgent]);
253	
254	  useEffect(() => {
255	    // update the basket customer email
256	    if (basket && customer?.isRegistered && customer?.email && customer?.email !== basket?.customerInfo?.email) {
257	      updateCustomerForBasket.mutate({
258	        parameters: { basketId: basket.basketId },
259	        body: {
260	          email: customer.email,
261	        },
262	      });
263	    }
264	    // matches upstream base _app exactly.
265	  }, [customer?.isRegistered, customer?.email, basket?.customerInfo?.email]);
266	
267	  useEffect(() => {
268	    // Listen for online status changes.
269	    watchOnlineStatus((online: boolean) => {
270	      setIsOnline(online);
271	    });
272	  }, []);
273	
274	  // Handle updating the shopper context
275	  useUpdateShopperContext();
276	
277	  useEffect(() => {
278	    // Lets automatically close the mobile navigation when the
279	    // location path is changed.
280	    onClose();
281	    // matches upstream base _app exactly.
282	  }, [location]);
283	
284	  const onLogoClick = (): void => {
285	    // Goto the home page.
286	    const path = buildUrl(HOME_HREF);
287	
288	    history.push(path);
289	
290	    // Close the drawer.
291	    onClose();
292	  };
293	
294	  const onCartClick = (): void => {
295	    const path = buildUrl('/cart');
296	    history.push(path);
297	
298	    // Close the drawer.
299	    onClose();
300	  };
301	
302	  const onAccountClick = (): void => {
303	    // Link to account page if registered; Header component will show auth modal for guest users
304	    const path = buildUrl('/account');
305	    history.push(path);
306	  };
307	
308	  const onWishlistClick = (): void => {
309	    // Link to wishlist page if registered; Header component will show auth modal for guest users
310	    const path = buildUrl('/account/wishlist');
311	    history.push(path);
312	  };
313	
314	  const { actions: shopperAgentActions } = useShopperAgent();
315	
316	  const trackPage = (): void => {
317	    activeData.trackPage(site.id, locale.id, currency);
318	  };
319	
320	  useEffect(() => {
321	    trackPage();
322	    // matches upstream base _app exactly.
323	  }, [location]);
324	
325	  const getHrefForLocale = (localeId: string): string =>
326	    `${appOrigin}${getRouterBasePath()}${getPathWithLocale(localeId, buildUrl, {
327	      location: { ...location, search: '' },
328	    })}`;
329	
330	  return (
331	    <Box className="sf-app" {...styles.container}>
332	      <StorefrontPreview getToken={getTokenWhenReady} getBasePath={getRouterBasePath}>
333	        <IntlProvider
334	          onError={(err) => {
335	            if (!messages) {
336	              // During the ssr prepass phase the messages object has not loaded, so we can suppress
337	              // errors during this time.
338	              return;
339	            }
340	            if (err.code === 'MISSING_TRANSLATION') {
341	              // NOTE: Remove the console error for missing translations during development,
342	              // as we knew translations would be added later.
343	              logger.warn('Missing translation', {
344	                namespace: 'App.IntlProvider',
345	                additionalProperties: {
346	                  errorMessage: err.message,
347	                },
348	              });
349	              return;
350	            }
351	            throw err;
352	          }}
353	          locale={targetLocale}
354	          messages={messages}
355	          // For react-intl, the _default locale_ refers to the locale that the inline `defaultMessage`s are written for.
356	          // NOTE: if you update this value, please also update the following npm scripts in `template-retail-react-app/package.json`:
357	          // - "extract-default-translations"
358	          // - "compile-translations:pseudo"
359	          defaultLocale={DEFAULT_LOCALE}
360	        >
361	          <CurrencyProvider currency={currency}>
362	            <Seo>
363	              <meta name="theme-color" content={THEME_COLOR} />
364	              <meta name="apple-mobile-web-app-title" content={DEFAULT_SITE_TITLE} />
365	              <link rel="apple-touch-icon" href={getAssetUrl('static/img/global/apple-touch-icon.png')} />
366	              <link rel="manifest" href={getAssetUrl('static/manifest.json')} />
367	
368	              {/* Urls for all localized versions of this page (including current page)
369	              For more details on hrefLang, see https://developers.google.com/search/docs/advanced/crawling/localized-versions */}
370	              {site.l10n?.supportedLocales.map((l: { id: string }) => (
371	                <link rel="alternate" hrefLang={l.id.toLowerCase()} href={getHrefForLocale(l.id)} key={l.id} />
372	              ))}
373	              {/* A general locale as fallback. For example: "en" if default locale is "en-GB" */}
374	              <link rel="alternate" hrefLang={site.l10n.defaultLocale.slice(0, 2)} href={getHrefForLocale(locale.id)} />
375	              {/* A wider fallback for user locales that the app does not support */}
376	              <link rel="alternate" hrefLang="x-default" href={`${appOrigin}/`} />
377	            </Seo>
378	
379	            {commerceAgentConfiguration?.enabled === 'true' && (
380	              <ShopperAgent
381	                commerceAgentConfiguration={commerceAgentConfiguration}
382	                basketDoneLoading={basketQueryLastUpdateTime > 0}
383	              />
384	            )}
385	
386	            <ScrollToTop />
387	
388	            <Box id="app" display="flex" flexDirection="column" flex={1}>
389	              <SkipNavLink zIndex="skipLink">Skip to Content</SkipNavLink>
390	              {storeLocatorEnabled && <StoreLocatorModal isOpen={isStoreLocatorOpen} onClose={onCloseStoreLocator} />}
391	              <Island hydrateOn={'visible'}>
392	                <Box {...styles.headerWrapper}>
393	                  {!isCheckout ? (
394	                    <>
395	                      <AboveHeader />
396	                      <Header
397	                        onMenuClick={onOpen}
398	                        onLogoClick={onLogoClick}
399	                        onMyCartClick={onCartClick}
400	                        onMyAccountClick={onAccountClick}
401	                        onWishlistClick={onWishlistClick}
402	                        onStoreLocatorClick={onOpenStoreLocator}
403	                        onAgentClick={shopperAgentActions.open}
404	                      >
405	                        <HideOnDesktop>
406	                          <DrawerMenu
407	                            isOpen={isOpen}
408	                            onClose={onClose}
409	                            onLogoClick={onLogoClick}
410	                            root={categories?.[CAT_MENU_DEFAULT_ROOT_CATEGORY]}
411	                            itemsKey="categories"
412	                            itemsCountKey="onlineSubCategoriesCount"
413	                            itemComponent={DrawerMenuItemWithData}
414	                          />
415	                        </HideOnDesktop>
416	
417	                        <HideOnMobile>
418	                          <ListMenu
419	                            root={categories?.[CAT_MENU_DEFAULT_ROOT_CATEGORY]}
420	                            itemsKey="categories"
421	                            itemsCountKey="onlineSubCategoriesCount"
422	                            contentComponent={ListMenuContentWithData}
423	                          />
424	                        </HideOnMobile>
425	                      </Header>
426	                    </>
427	                  ) : (
428	                    <CheckoutHeader />
429	                  )}
430	                </Box>
431	              </Island>
432	              {!isOnline && <OfflineBanner />}
433	              <AddToCartModalProvider>
434	                <BonusProductSelectionModalProvider>
435	                  <SkipNavContent
436	                    style={{
437	                      display: 'flex',
438	                      flexDirection: 'column',
439	                      flex: 1,
440	                      outline: 0,
441	                    }}
442	                  >
443	                    <Box as="main" id="app-main" role="main" display="flex" flexDirection="column" flex="1">
444	                      <OfflineBoundary isOnline={false}>
445	                        <PageDesignerProvider
446	                          clientId="pwa-kit-client"
447	                          targetOrigin="*"
448	                          usid={usid ?? undefined}
449	                          mode={pageDesignerMode}
450	                        >
451	                          <PageDesignerInit />
452	                          {children}
453	                        </PageDesignerProvider>
454	                      </OfflineBoundary>
455	                    </Box>
456	                  </SkipNavContent>
457	
458	                  <Island hydrateOn={'visible'}>{!isCheckout ? <Footer /> : <CheckoutFooter />}</Island>
459	
460	                  <AuthModal {...authModal} />
461	                </BonusProductSelectionModalProvider>
462	              </AddToCartModalProvider>
463	            </Box>
464	          </CurrencyProvider>
465	        </IntlProvider>
466	      </StorefrontPreview>
467	    </Box>
468	  );
469	};
470	
471	export default App;
