1	import React from 'react';
2	import { Box } from '@salesforce/retail-react-app/app/components/shared/ui';
3	import type { BoxProps } from '@chakra-ui/layout';
4	
5	// Override of base responsive/index.jsx: base hardcodes Chakra's default `lg` (992px) as the
6	// mobile/desktop split. Zimmermann's own breakpoint system treats `md` (768px, gridSystem.ts,
7	// registered as theme.breakpoints.md) as that split everywhere else (header, footer, mega
8	// menu) — using `lg` here left a dead zone between 768-991px where content wrapped in both
9	// helpers was simultaneously hidden.
10	const MOBILE_DESKTOP_SPLIT = 'md';
11	
12	type ResponsiveVisibilityProps = BoxProps & {
13	  children?: React.ReactNode;
14	};
15	
16	export const HideOnDesktop = ({ children, ...rest }: ResponsiveVisibilityProps) => (
17	  <Box display={{ base: 'block', [MOBILE_DESKTOP_SPLIT]: 'none' }} {...rest}>
18	    {children}
19	  </Box>
20	);
21	
22	export const HideOnMobile = ({ children, ...rest }: ResponsiveVisibilityProps) => (
23	  <Box display={{ base: 'none', [MOBILE_DESKTOP_SPLIT]: 'block' }} {...rest}>
24	    {children}
25	  </Box>
26	);
27	
28	export default { HideOnMobile, HideOnDesktop };
