1	import React from 'react';
2	import { describe, test, expect, vi } from 'vitest';
3	import { render, screen } from '@testing-library/react';
4	
5	// SFCC-863 — the whole point of this suite: DntNotification (Salesforce's placeholder
6	// consent-tracking modal, real Lorem ipsum body copy, no config flag to disable it) must never
7	// render. Mocked with spies rather than simply left unmocked so a future regression (an
8	// upstream sync re-adding the import/hook-call/JSX this story removed) is actually caught —
9	// an unmocked, unimported dependency would make this suite pass trivially either way.
10	const useDntNotification = vi.fn(() => ({ isOpen: false, onOpen: vi.fn(), onClose: vi.fn() }));
11	const DntNotification = vi.fn((props: unknown) => (
12	  <div data-testid="dnt-notification-placeholder" data-props={JSON.stringify(props)}>
13	    Lorem ipsum
14	  </div>
15	));
16	vi.mock('@salesforce/retail-react-app/app/hooks/use-dnt-notification', () => ({
17	  useDntNotification: () => useDntNotification(),
18	  DntNotification: (props: unknown) => DntNotification(props),
19	}));
20	
21	// Everything below is mocked at the smallest surface needed to render App's tree without
22	// crashing — per testing.md, each dependency's own behaviour is already covered by its own
23	// suite (Header/Footer/DrawerMenu/ListMenu each have their own index.test.tsx; the base SFCC
24	// hooks are Salesforce's own tested code). This suite asserts only App's own contract: that it
25	// no longer wires up DntNotification, and that the sibling AuthModal survived the edit intact.
26	vi.mock('react-router-dom', () => ({
27	  useHistory: () => ({ push: vi.fn() }),
28	  useLocation: () => ({ pathname: '/', search: '' }),
29	}));
30	// Subpath export — not resolvable under Vitest without an explicit mock (see testing.md's
31	// ZimmIcon gap for the same subpath-resolution shape of problem).
32	vi.mock('@salesforce/commerce-sdk-react/components', () => ({
33	  StorefrontPreview: ({ children }: { children: React.ReactNode }) => <>{children}</>,
34	}));
35	vi.mock('@salesforce/pwa-kit-react-sdk/ssr/universal/utils', () => ({
36	  getAssetUrl: (path: string) => `/mocked/${path}`,
37	  getRouterBasePath: () => '',
38	}));
39	vi.mock('@salesforce/retail-react-app/app/hooks/use-active-data', () => ({
40	  default: () => ({ trackPage: vi.fn() }),
41	}));
42	vi.mock('@salesforce/retail-react-app/app/contexts', () => ({
43	  CurrencyProvider: ({ children }: { children: React.ReactNode }) => <>{children}</>,
44	}));
45	vi.mock('@tanstack/react-query', () => ({
46	  useQuery: () => ({ data: {} }),
47	}));
48	vi.mock('@salesforce/commerce-sdk-react', () => ({
49	  useAccessToken: () => ({ getTokenWhenReady: vi.fn() }),
50	  useCategory: () => ({ data: undefined }),
